window.docContents[57].resolve({"/3___-General-results-of-representation-theory/3___5___-Finite-dimensional-algebras/Radical-of-a-finite-dimensional-algebra/#Chapter3___Definition3___5___1":{"contents":"Definition 3.5.1. The radical of a finite dimensional algebra A is the set of all elements of A which act by 0 in all irreducible representations of A. It is denoted \\operatorname{Rad}(A).\n\n\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory\t3.5. Finite dimensional algebras\tRadical of a finite dimensional algebra","header":"Radical of a finite dimensional algebra","id":"/3___-General-results-of-representation-theory/3___5___-Finite-dimensional-algebras/Radical-of-a-finite-dimensional-algebra/#Chapter3___Definition3___5___1"},"/4___-Representations-of-finite-groups___-Basic-results/4___2___-Characters/Representations-determined-by-characters-in-characteristic-0/#Chapter4___Corollary4___2___4":{"contents":"Corollary 4.2.4. Any finite dimensional representation of G is determined by its character if k has characteristic 0; namely, \\chi_V = \\chi_W implies V \\cong W.\n\n\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results\t4.2. Characters\tRepresentations determined by characters in characteristic 0","header":"Representations determined by characters in characteristic 0","id":"/4___-Representations-of-finite-groups___-Basic-results/4___2___-Characters/Representations-determined-by-characters-in-characteristic-0/#Chapter4___Corollary4___2___4"},"/4___-Representations-of-finite-groups___-Basic-results/4___5___-Orthogonality-of-characters/#chapter-04___section-4-5":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results","header":"4.5. Orthogonality of characters","id":"/4___-Representations-of-finite-groups___-Basic-results/4___5___-Orthogonality-of-characters/#chapter-04___section-4-5"}});
